const msg = $json.message;

if (!msg || !msg.from) {
  // Ignora updates sin remitente (ediciones, canal, etc.)
  return [];
}

return {
  json: {
    telegram_user: String(msg.from.id),
    user_name: msg.from.first_name || 'Usuario',
    input_text: msg.text ? msg.text.trim() : '',
    chat_id: msg.chat.id,
    timestamp: new Date().toISOString()
  }
};

const filas = $('Get Session').all();
const pantalla = (filas[0] && filas[0].json.pantalla_actual) || 'MAIN_MENU';

const AGENDA = ['MENU_AGENDA','WIZARD_CITA','WIZARD_CANCELAR_CITA','WIZARD_COMPLETAR_CITA','WIZARD_REPROGRAMAR_CITA','POST_ACCION_AGENDA'];
const TAREAS = ['MENU_TAREAS','WIZARD_TAREA','WIZARD_COMPLETAR_TAREA','POST_ACCION_TAREAS'];
const HABITOS = ['MENU_HABITOS','WIZARD_HABITO','WIZARD_MARCAR_HABITO','POST_ACCION_HABITOS','MENU_RECORDATORIOS'];
const LISTAS = ['MENU_LISTAS','WIZARD_LISTA','WIZARD_ITEM','WIZARD_VER_ITEMS','WIZARD_MARCAR_ITEM','POST_ACCION_LISTAS'];
const REPORTES = ['MENU_REPORTES'];
const ADMIN = ['MENU_ADMIN'];

return {
  json: {
    ...$json,
    necesita_citas: AGENDA.includes(pantalla) || REPORTES.includes(pantalla),
    necesita_tareas: TAREAS.includes(pantalla) || REPORTES.includes(pantalla),
    necesita_habitos: HABITOS.includes(pantalla) || REPORTES.includes(pantalla),
    necesita_listas: LISTAS.includes(pantalla) || REPORTES.includes(pantalla),
    necesita_admin: ADMIN.includes(pantalla),
  }
};

const original = $('Normalizar Input').all();
if (!original || original.length === 0) {
  return [];
}
return [{ json: original[0].json }];

/**
 * ============================================================
 *  AGENDABOT SERVICES — MOTOR DE MÁQUINA DE ESTADOS ("BRAIN")
 *  v2 — Comunicación Humanizada (Artículos 6 a 10)
 * ============================================================
 * Nodo: Code (JavaScript) — Modo: "Run Once for Each Item"
 *
 * ENTRADAS (pipeline lineal de n8n):
 *   $json                         -> salida de "Normalizar Input"
 *   obtenerFilas('Get Session')        -> SESSIONS para este telegram_user
 *   obtenerFilas('Get Usuario')        -> USUARIOS para este telegram_user
 *   obtenerFilas('Get Citas Activas')  -> CITAS con fecha >= hoy
 *
 * SALIDA: igual contrato que v1 (reply_text, session, write, log).
 *
 * REGLA DE COMUNICACIÓN HUMANIZADA (aplica a TODO mensaje del bot):
 *   1. Saludar / dar contexto cercano
 *   2. Explicar brevemente qué se puede hacer ahí
 *   3. Mostrar opciones numeradas
 *   4. Sugerir una opción
 *   5. Indicar cómo continuar o salir (9 = volver)
 * ============================================================
 */

// ---------- 0. UTILIDADES ----------

function hoyISO() {
  return new Date().toISOString().slice(0, 10);
}
function nowISO() {
  return new Date().toISOString();
}
function validarFecha(str) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(str)) return false;
  const d = new Date(str + 'T00:00:00');
  if (isNaN(d.getTime())) return false;
  const hoy = new Date(hoyISO() + 'T00:00:00');
  return d.getTime() >= hoy.getTime();
}
function validarHora(str) {
  return /^([01]\d|2[0-3]):[0-5]\d$/.test(str);
}
function generarId(prefijo, filasExistentes, campoId) {
  let max = 0;
  for (const fila of filasExistentes) {
    const val = String(fila.json[campoId] || '');
    const m = val.match(/-(\d+)$/);
    if (m) {
      const n = parseInt(m[1], 10);
      if (n > max) max = n;
    }
  }
  return `${prefijo}-${String(max + 1).padStart(3, '0')}`;
}
function parseDatosParciales(str) {
  try {
    return str ? JSON.parse(str) : {};
  } catch (e) {
    return {};
  }
}

// Lee $('NodeName').all() de forma segura. Con el nuevo diseño de lecturas
// condicionales (Fase de optimización), varios nodos Google Sheets solo se
// ejecutan cuando la pantalla actual realmente los necesita — si el nodo no
// corrió en esta ejecución, $('NodeName') lanza un error. Esta función lo
// captura y devuelve un arreglo vacío en su lugar.
function obtenerFilas(nombreNodo) {
  try {
    return $(nombreNodo).all();
  } catch (e) {
    return [];
  }
}

// ---------- 1. MENÚ PRINCIPAL Y TEXTOS BASE (Artículos 6, 7, 8) ----------

function textoMenuPrincipal() {
  return (
    `0. Ayuda\n` +
    `1. Agenda (citas)\n` +
    `2. Tareas\n` +
    `3. Recordatorios\n` +
    `4. Hábitos\n` +
    `5. Listas\n` +
    `6. Reportes\n` +
    `7. Configuración\n` +
    `8. Administrador`
  );
}

// Artículo 6 — se muestra solo la primera vez (sesión nueva)
function bienvenida() {
  return (
    `Hola, soy AgendaBot 👋\n\n` +
    `Estoy aquí para ayudarte a organizar tus citas, tareas y recordatorios ` +
    `de forma sencilla y sin complicaciones.\n\n` +
    `Puedes escribirme en cualquier momento.\n` +
    `Para avanzar, solo tienes que escribir el número de la opción que quieras usar.\n\n` +
    `Menú principal:\n${textoMenuPrincipal()}\n\n` +
    `Tip rápido: escribe solo el número (por ejemplo: 1) y presiona enviar.`
  );
}

// Artículo 8 — se muestra cada vez que se vuelve al menú principal
function menuPrincipal() {
  return (
    `¿En qué te puedo ayudar hoy?\n\n` +
    `Menú principal:\n${textoMenuPrincipal()}\n\n` +
    `Si quieres empezar rápido, te recomiendo la opción 1 (Agenda).`
  );
}

// Artículo 7 — mensaje global de opción inválida (dinámico)
const PANTALLAS_INFO = {
  MAIN_MENU:          { label: 'Menú principal',       rango: '0 al 8' },
  MENU_AGENDA:        { label: 'Menú de Agenda',        rango: '1 al 5, o 9 para volver' },
  MENU_TAREAS:        { label: 'Menú de Tareas',        rango: '1 al 3, o 9 para volver' },
  MENU_RECORDATORIOS: { label: 'Menú de Recordatorios', rango: '1 al 2, o 9 para volver' },
  MENU_HABITOS:       { label: 'Menú de Hábitos',       rango: '1 al 3, o 9 para volver' },
  MENU_LISTAS:        { label: 'Menú de Listas',        rango: '1 al 5, o 9 para volver' },
  MENU_REPORTES:      { label: 'Menú de Reportes',      rango: '1 al 2, o 9 para volver' },
  MENU_CONFIGURACION: { label: 'Configuración',         rango: '1 al 2, o 9 para volver' },
  MENU_ADMIN:         { label: 'Administrador',         rango: '1 al 2, o 9 para volver' },
};

function mensajeOpcionInvalida(pantalla) {
  const info = PANTALLAS_INFO[pantalla] || { label: pantalla, rango: 'revisa las opciones en pantalla' };
  return (
    `Ups, esa opción no existe en este menú.\n\n` +
    `Por favor escribe uno de los números que ves en pantalla.\n\n` +
    `Estás en: ${info.label}\n` +
    `Opciones disponibles: ${info.rango}`
  );
}

// ---------- 2. MENÚS DE SEGUNDO NIVEL ----------

function menuAgenda() {
  return (
    `Perfecto, vamos con tu agenda.\n\n` +
    `¿Qué deseas hacer?\n\n` +
    `1. Agendar una nueva cita\n` +
    `2. Consultar tu agenda\n` +
    `3. Reprogramar una cita\n` +
    `4. Cancelar una cita\n` +
    `5. Marcar una cita como completada\n` +
    `9. Volver al menú principal`
  );
}

function menuTareas() {
  return (
    `Vamos con tus tareas — aquí puedes crearlas, revisarlas o completarlas.\n\n` +
    `¿Qué deseas hacer?\n\n` +
    `1. Crear una tarea\n` +
    `2. Consultar tareas pendientes\n` +
    `3. Marcar una tarea como completada\n` +
    `9. Volver al menú principal\n\n` +
    `💡 Si es tu primera vez aquí, te recomiendo la opción 1.`
  );
}

function menuRecordatorios() {
  return (
    `Vamos con tus recordatorios — para que no se te pase nada importante.\n\n` +
    `Tus recordatorios se basan en los hábitos que tengan una hora configurada.\n\n` +
    `¿Qué deseas hacer?\n\n` +
    `1. Ver mis recordatorios\n` +
    `2. Ir a Hábitos para crear o editar uno\n` +
    `9. Volver al menú principal`
  );
}

function menuHabitos() {
  return (
    `Vamos con tus hábitos — para ayudarte a seguirles la pista.\n\n` +
    `¿Qué deseas hacer?\n\n` +
    `1. Crear un hábito\n` +
    `2. Consultar mis hábitos\n` +
    `3. Marcar cumplido hoy\n` +
    `9. Volver al menú principal\n\n` +
    `💡 Si es tu primer hábito, te recomiendo la opción 1.`
  );
}

function menuListas() {
  return (
    `Vamos con tus listas — de compras, pendientes o lo que necesites.\n\n` +
    `¿Qué deseas hacer?\n\n` +
    `1. Crear una lista\n` +
    `2. Consultar mis listas\n` +
    `3. Agregar un item a una lista\n` +
    `4. Marcar un item como completado\n` +
    `5. Ver los items de una lista\n` +
    `9. Volver al menú principal\n\n` +
    `💡 Si es tu primera lista, te recomiendo la opción 1.`
  );
}

function menuReportes(citasActivas, tareasActivas, habitos, listas) {
  const confirmadas = citasActivas.filter(c => String(c.json.estado).toUpperCase() === 'CONFIRMADA').length;
  const canceladas = citasActivas.filter(c => String(c.json.estado).toUpperCase() === 'CANCELADA').length;
  const tareasPendientes = tareasActivas.filter(t => String(t.json.estado).toUpperCase() !== 'COMPLETADA').length;
  const habitosActivos = habitos.filter(h => String(h.json.estado || '').toUpperCase() !== 'INACTIVO').length;
  return (
    `Aquí tienes un vistazo rápido a tu actividad.\n\n` +
    `📊 Citas activas confirmadas: ${confirmadas}\n` +
    `📊 Citas canceladas (histórico visible): ${canceladas}\n` +
    `📊 Tareas pendientes: ${tareasPendientes}\n` +
    `📊 Hábitos activos: ${habitosActivos}\n` +
    `📊 Listas creadas: ${listas.length}\n\n` +
    `¿Qué deseas hacer?\n\n` +
    `1. Ver este resumen de nuevo\n` +
    `2. Ver citas de hoy\n` +
    `9. Volver al menú principal`
  );
}

function menuConfiguracion() {
  return (
    `Aquí puedes ajustar tus preferencias.\n\n` +
    `¿Qué deseas hacer?\n\n` +
    `1. Ver mis datos registrados\n` +
    `2. Cambiar mi nombre visible\n` +
    `9. Volver al menú principal`
  );
}

function menuAdmin() {
  return (
    `Panel de administrador — solo visible para roles ADMIN.\n\n` +
    `¿Qué deseas hacer?\n\n` +
    `1. Ver últimos logs\n` +
    `2. Ver usuarios registrados\n` +
    `9. Volver al menú principal`
  );
}

function menuAyuda() {
  return (
    `Con gusto te oriento 🙂\n\n` +
    `AgendaBot funciona con menús numerados: escribe el número de la opción ` +
    `que quieras y presiona enviar.\n\n` +
    `Desde cualquier submenú o asistente paso a paso, escribe 9 para volver ` +
    `al menú anterior en cualquier momento.\n\n` +
    `¿Qué deseas hacer?\n\n` +
    `1. Ver el menú principal de nuevo\n` +
    `9. Volver al menú principal\n\n` +
    `💡 Si tienes dudas sobre una opción específica, entra a ese menú: ` +
    `siempre te va a explicar brevemente qué puedes hacer ahí.`
  );
}

// ---------- 3. NODO PRINCIPAL DE EJECUCIÓN ----------

const input = $json;
const telegramUser = input.telegram_user;
const chatId = input.chat_id;
const texto = (input.input_text || '').trim();
const nombre = input.user_name || 'Usuario';

const sesionRows = obtenerFilas('Get Session').filter(r => String(r.json.telegram_user) === String(telegramUser));
const usuarioRows = obtenerFilas('Get Usuario').filter(r => String(r.json.telegram_user) === String(telegramUser));
const citasActivas = obtenerFilas('Get Citas Activas');
const tareasActivas = obtenerFilas('Get Tareas Activas');
const habitosTodos = obtenerFilas('Get Habitos');
const listasTodas = obtenerFilas('Get Listas');

const esUsuarioNuevo = usuarioRows.length === 0;
const usuario = esUsuarioNuevo
  ? { telegram_user: telegramUser, nombre, rol: 'USER', permitido: 'TRUE' }
  : usuarioRows[0].json;

const esAdmin = String(usuario.rol).toUpperCase() === 'ADMIN' &&
                 String(usuario.permitido).toUpperCase() === 'TRUE';

const esSesionNueva = sesionRows.length === 0;
let sesion = esSesionNueva
  ? { telegram_user: telegramUser, pantalla_actual: 'MAIN_MENU', paso_actual: 0, datos_parciales: '{}' }
  : sesionRows[0].json;

let pantalla = sesion.pantalla_actual || 'MAIN_MENU';
let paso = Number(sesion.paso_actual || 0);
let datos = parseDatosParciales(sesion.datos_parciales);

const write = {
  citas:  { do: false, row: null },
  tareas: { do: false, row: null },
  habitos:{ do: false, row: null },
  listas: { do: false, row: null },
  items:  { do: false, row: null },
  usuarios_nuevo: { do: esUsuarioNuevo, row: esUsuarioNuevo ? usuario : null },
  usuario_actualizar: { do: false, row: null },
};

let reply = '';
let resultadoLog = 'OK';

function volverAMenuPrincipal() {
  pantalla = 'MAIN_MENU';
  paso = 0;
  datos = {};
  reply = menuPrincipal();
}

// Sesión nueva → Artículo 6 (bienvenida), sin importar qué haya escrito
if (esSesionNueva) {
  pantalla = 'MAIN_MENU';
  paso = 0;
  datos = {};
  reply = bienvenida();
  resultadoLog = 'BIENVENIDA';
} else if (pantalla !== 'MAIN_MENU' && texto === '9') {
  volverAMenuPrincipal();
  resultadoLog = 'VOLVIO_MENU_PRINCIPAL';
} else {
  switch (pantalla) {

    // =====================================================
    case 'MAIN_MENU': {
      switch (texto) {
        case '0':
          reply = menuAyuda();
          break;
        case '1':
          pantalla = 'MENU_AGENDA';
          reply = menuAgenda();
          break;
        case '2':
          pantalla = 'MENU_TAREAS';
          reply = menuTareas();
          break;
        case '3':
          pantalla = 'MENU_RECORDATORIOS';
          reply = menuRecordatorios();
          break;
        case '4':
          pantalla = 'MENU_HABITOS';
          reply = menuHabitos();
          break;
        case '5':
          pantalla = 'MENU_LISTAS';
          reply = menuListas();
          break;
        case '6':
          pantalla = 'MENU_REPORTES';
          reply = menuReportes(citasActivas, tareasActivas, habitosTodos, listasTodas);
          break;
        case '7':
          pantalla = 'MENU_CONFIGURACION';
          reply = menuConfiguracion();
          break;
        case '8':
          if (esAdmin) {
            pantalla = 'MENU_ADMIN';
            reply = menuAdmin();
          } else {
            reply = 'Esa sección es solo para administradores. No tienes permiso para entrar ahí.\n\n' + menuPrincipal();
            resultadoLog = 'ACCESO_DENEGADO';
          }
          break;
        default:
          reply = mensajeOpcionInvalida('MAIN_MENU');
          resultadoLog = 'OPCION_INVALIDA';
      }
      break;
    }

    // =====================================================
    case 'MENU_AGENDA': {
      switch (texto) {
        case '1':
          pantalla = 'WIZARD_CITA';
          paso = 1;
          datos = {};
          reply =
            `Empecemos a crear tu cita.\n\n` +
            `Paso 1 de 6\n¿Cuál es la fecha de la cita?\n\n` +
            `Formato: YYYY-MM-DD\nEjemplo: 2025-12-20\n\n9. Cancelar`;
          break;
        case '2': {
          if (citasActivas.length === 0) {
            reply = 'Todavía no tienes citas agendadas.\n\n' + menuAgenda();
          } else {
            const lineas = citasActivas
              .sort((a, b) => (a.json.fecha + a.json.hora).localeCompare(b.json.fecha + b.json.hora))
              .map(c => `• [${c.json.id_cita}] ${c.json.fecha} ${c.json.hora} — ${c.json.nombre} (${c.json.motivo}, ${c.json.canal})`)
              .join('\n');
            reply = `Aquí están tus próximas citas:\n\n${lineas}\n\n` + menuAgenda();
          }
          break;
        }
        case '3':
          if (citasActivas.length === 0) {
            reply = 'No tienes citas activas para reprogramar.\n\n' + menuAgenda();
          } else {
            pantalla = 'WIZARD_REPROGRAMAR_CITA';
            paso = 1;
            datos = {};
            const lineas = citasActivas.map(c => `• [${c.json.id_cita}] ${c.json.fecha} ${c.json.hora} — ${c.json.nombre}`).join('\n');
            reply = `Vamos a reprogramar una cita.\n\nEscribe el ID de la cita:\n\n${lineas}\n\n9. Cancelar`;
          }
          break;
        case '4':
          if (citasActivas.length === 0) {
            reply = 'No tienes citas activas para cancelar.\n\n' + menuAgenda();
          } else {
            pantalla = 'WIZARD_CANCELAR_CITA';
            paso = 1;
            datos = {};
            const lineas = citasActivas.map(c => `• [${c.json.id_cita}] ${c.json.fecha} ${c.json.hora} — ${c.json.nombre}`).join('\n');
            reply = `Entiendo, vamos a cancelar una cita.\n\nEscribe el ID de la cita que quieres cancelar:\n\n${lineas}\n\n9. Volver`;
          }
          break;
        case '5':
          if (citasActivas.length === 0) {
            reply = 'No tienes citas activas para marcar como completadas.\n\n' + menuAgenda();
          } else {
            pantalla = 'WIZARD_COMPLETAR_CITA';
            paso = 1;
            datos = {};
            const lineas = citasActivas.map(c => `• [${c.json.id_cita}] ${c.json.fecha} ${c.json.hora} — ${c.json.nombre}`).join('\n');
            reply = `Vamos a marcarla como completada.\n\nEscribe el ID de la cita:\n\n${lineas}\n\n9. Volver`;
          }
          break;
        default:
          reply = mensajeOpcionInvalida('MENU_AGENDA');
          resultadoLog = 'OPCION_INVALIDA';
      }
      break;
    }

    // =====================================================
    case 'WIZARD_CITA': {
      switch (paso) {
        case 1: // Fecha
          if (!validarFecha(texto)) {
            reply =
              `Esa fecha no es válida — recuerda que debe tener el formato YYYY-MM-DD ` +
              `y no puede ser una fecha pasada.\n\nInténtalo de nuevo (ejemplo: 2025-12-20):\n\n9. Cancelar`;
            resultadoLog = 'VALIDACION_FALLIDA';
          } else {
            datos.fecha = texto;
            paso = 2;
            reply =
              `Perfecto.\n\nPaso 2 de 6\n¿A qué hora será la cita?\n\n` +
              `Formato 24 horas (HH:MM)\nEjemplo: 14:30\n\n9. Cancelar`;
          }
          break;

        case 2: // Hora
          if (!validarHora(texto)) {
            reply = `Esa hora no es válida. Usa formato 24 horas (HH:MM), por ejemplo 14:30.\n\nInténtalo de nuevo:\n\n9. Cancelar`;
            resultadoLog = 'VALIDACION_FALLIDA';
          } else {
            datos.hora = texto;
            paso = 3;
            reply = `Muy bien.\n\nPaso 3 de 6\n¿A nombre de quién es la cita?\n\nEscribe el nombre completo.\n\n9. Cancelar`;
          }
          break;

        case 3: // Nombre
          if (texto.length === 0) {
            reply = `El nombre no puede quedar vacío. Escríbelo de nuevo:\n\n9. Cancelar`;
            resultadoLog = 'VALIDACION_FALLIDA';
          } else {
            datos.nombre = texto;
            paso = 4;
            reply = `Gracias.\n\nPaso 4 de 6\nCuéntame brevemente el motivo de la cita.\n\nEjemplo: Asesoría técnica\n\n9. Cancelar`;
          }
          break;

        case 4: // Motivo
          if (texto.length === 0) {
            reply = `El motivo no puede quedar vacío. Escríbelo de nuevo:\n\n9. Cancelar`;
            resultadoLog = 'VALIDACION_FALLIDA';
          } else {
            datos.motivo = texto;
            paso = 5;
            reply = `Ya casi terminamos.\n\nPaso 5 de 6\n¿Cómo será la atención?\n\n1. Presencial\n2. Virtual\n3. Llamada\n9. Cancelar`;
          }
          break;

        case 5: { // Canal
          const canales = { '1': 'Presencial', '2': 'Virtual', '3': 'Llamada' };
          if (!canales[texto]) {
            reply = `Elige una opción válida: 1 (Presencial), 2 (Virtual) o 3 (Llamada).\n\n9. Cancelar`;
            resultadoLog = 'VALIDACION_FALLIDA';
          } else {
            datos.canal = canales[texto];
            paso = 6;
            reply =
              `Revisa la información de tu cita:\n\n` +
              `Fecha: ${datos.fecha}\n` +
              `Hora: ${datos.hora}\n` +
              `Cliente: ${datos.nombre}\n` +
              `Motivo: ${datos.motivo}\n` +
              `Canal: ${datos.canal}\n\n` +
              `¿Qué deseas hacer?\n1. Confirmar y guardar\n2. Editar información\n3. Cancelar`;
          }
          break;
        }

        case 6: { // Confirmación
          if (texto === '1') {
            const solapada = citasActivas.some(c => c.json.fecha === datos.fecha && c.json.hora === datos.hora);
            if (solapada) {
              reply =
                `Ya tienes otra cita agendada el ${datos.fecha} a las ${datos.hora}. Elijamos otro horario.\n\n` +
                `Paso 1 de 6\n¿Cuál es la fecha de la cita?\n\nFormato: YYYY-MM-DD\n\n9. Cancelar`;
              paso = 1;
              datos = {};
              resultadoLog = 'SOLAPAMIENTO_DETECTADO';
            } else {
              const idCita = generarId('CITA', citasActivas, 'id_cita');
              write.citas = {
                do: true,
                operation: 'append',
                row: {
                  id_cita: idCita,
                  fecha: datos.fecha,
                  hora: datos.hora,
                  nombre: datos.nombre,
                  motivo: datos.motivo,
                  canal: datos.canal,
                  estado: 'CONFIRMADA',
                  creado_por: telegramUser,
                  timestamp_creacion: nowISO(),
                },
              };
              reply =
