    case 'POST_ACCION_LISTAS': {
      if (texto === '1') { pantalla = 'MENU_LISTAS'; reply = menuListas(); }
      else if (texto === '2') { pantalla = 'MAIN_MENU'; reply = menuPrincipal(); }
      else { reply = 'Elige 1 (Volver a Listas) o 2 (Ir al menú principal).'; resultadoLog = 'VALIDACION_FALLIDA'; }
      break;
    }

    // =====================================================
    case 'MENU_REPORTES': {
      switch (texto) {
        case '1':
          reply = menuReportes(citasActivas, tareasActivas, habitosTodos, listasTodas);
          break;
        case '2': {
          const hoy = hoyISO();
          const citasHoy = citasActivas.filter(c => c.json.fecha === hoy);
          reply = citasHoy.length === 0
            ? 'No tienes citas hoy.\n\n' + menuReportes(citasActivas, tareasActivas, habitosTodos, listasTodas)
            : `Citas de hoy:\n\n${citasHoy.map(c => `• ${c.json.hora} — ${c.json.nombre}`).join('\n')}\n\n` + menuReportes(citasActivas, tareasActivas, habitosTodos, listasTodas);
          break;
        }
        default:
          reply = mensajeOpcionInvalida('MENU_REPORTES');
          resultadoLog = 'OPCION_INVALIDA';
      }
      break;
    }

    // =====================================================
    case 'MENU_CONFIGURACION': {
      switch (texto) {
        case '1':
          reply =
            `Estos son tus datos registrados:\n\n` +
            `Nombre: ${usuario.nombre}\n` +
            `ID de Telegram: ${usuario.telegram_user}\n` +
            `Rol: ${usuario.rol}\n` +
            `Permitido: ${usuario.permitido}\n\n` +
            menuConfiguracion();
          break;
        case '2':
          pantalla = 'WIZARD_CAMBIAR_NOMBRE';
          paso = 1;
          datos = {};
          reply = `Tu nombre actual es "${usuario.nombre}".\n\n¿Cuál quieres que sea tu nuevo nombre visible?\n\n9. Cancelar`;
          break;
        default:
          reply = mensajeOpcionInvalida('MENU_CONFIGURACION');
          resultadoLog = 'OPCION_INVALIDA';
      }
      break;
    }

    case 'WIZARD_CAMBIAR_NOMBRE': {
      if (texto.length === 0) {
        reply = 'El nombre no puede quedar vacío. Escríbelo de nuevo:\n\n9. Cancelar';
        resultadoLog = 'VALIDACION_FALLIDA';
      } else {
        write.usuario_actualizar = { do: true, row: { telegram_user: telegramUser, nombre: texto } };
        reply = `Listo, tu nombre visible ahora es "${texto}".\n\n¿Qué deseas hacer ahora?\n1. Volver a Configuración\n2. Ir al menú principal`;
        pantalla = 'POST_ACCION_CONFIGURACION';
        paso = 0;
        datos = {};
      }
      break;
    }

    case 'POST_ACCION_CONFIGURACION': {
      if (texto === '1') { pantalla = 'MENU_CONFIGURACION'; reply = menuConfiguracion(); }
      else if (texto === '2') { pantalla = 'MAIN_MENU'; reply = menuPrincipal(); }
      else { reply = 'Elige 1 (Volver a Configuración) o 2 (Ir al menú principal).'; resultadoLog = 'VALIDACION_FALLIDA'; }
      break;
    }

    // =====================================================
    case 'MENU_ADMIN': {
      if (!esAdmin) {
        reply = 'Acceso restringido.\n\n' + menuPrincipal();
        pantalla = 'MAIN_MENU';
        paso = 0;
        resultadoLog = 'ACCESO_DENEGADO';
        break;
      }
      switch (texto) {
        case '1': {
          const logs = obtenerFilas('Get Logs')
            .filter(l => l.json.timestamp)
            .sort((a, b) => String(b.json.timestamp).localeCompare(String(a.json.timestamp)))
            .slice(0, 10);
          if (logs.length === 0) {
            reply = 'Todavía no hay registros en el log.\n\n' + menuAdmin();
          } else {
            const lineas = logs
              .map(l => `• ${l.json.timestamp} — [${l.json.telegram_user}] ${l.json.pantalla} → "${l.json.opcion_elegida}" (${l.json.resultado})`)
              .join('\n');
            reply = `Últimos ${logs.length} registros:\n\n${lineas}\n\n` + menuAdmin();
          }
          break;
        }
        case '2': {
          const usuarios = obtenerFilas('Get Todos Usuarios');
          if (usuarios.length === 0) {
            reply = 'No hay usuarios registrados.\n\n' + menuAdmin();
          } else {
            const lineas = usuarios
              .map(u => `• ${u.json.nombre} [${u.json.telegram_user}] — Rol: ${u.json.rol} — Permitido: ${u.json.permitido}`)
              .join('\n');
            reply = `Usuarios registrados (${usuarios.length}):\n\n${lineas}\n\n` + menuAdmin();
          }
          break;
        }
        default:
          reply = mensajeOpcionInvalida('MENU_ADMIN');
          resultadoLog = 'OPCION_INVALIDA';
      }
      break;
    }

    // =====================================================
    default:
      volverAMenuPrincipal();
      resultadoLog = 'PANTALLA_DESCONOCIDA';
  }
}

// ---------- 4. SALIDA ----------

const sesionFinal = {
  telegram_user: telegramUser,
  pantalla_actual: pantalla,
  paso_actual: paso,
  datos_parciales: JSON.stringify(datos),
  timestamp_ultima_interaccion: nowISO(),
};

return {
  json: {
    telegram_user: telegramUser,
    chat_id: chatId,
    reply_text: reply,
    session: sesionFinal,
    is_new_session: esSesionNueva,
    write,
    log: {
      timestamp: nowISO(),
      telegram_user: telegramUser,
      pantalla: sesion.pantalla_actual || 'MAIN_MENU',
      opcion_elegida: texto,
      resultado: resultadoLog,
    },
  },
};
